package deploy

import (
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// Upstream statuses. All four are informational: none of them can fail a
// deployment.
const (
	// UpstreamMatch means every image is pinned there to the digest being
	// deployed here.
	UpstreamMatch = "match"

	// UpstreamDiffers means it pins a digest, but a different one.
	UpstreamDiffers = "differs"

	// UpstreamUnpinned means it pins a tag, or nothing, for some image — so
	// there is no digest to compare.
	UpstreamUnpinned = "unpinned"

	// UpstreamUnknown means it could not be read: the component is not
	// onboarded there, or its overlay is unreadable.
	UpstreamUnknown = "unknown"
)

// Upstream is what an environment this one promotes from currently has pinned.
type Upstream struct {
	Environment string `json:"environment"`
	Status      string `json:"status"`

	// Pinned is how that overlay pins each image, keyed by image name, in the
	// same form as Plan.Previous. A missing key means the overlay has no entry
	// for that image.
	Pinned map[string]string `json:"pinned,omitempty"`

	// SourceCommit is the deploy.internal/source-commit annotation that
	// overlay carries, empty when it has none.
	SourceCommit string `json:"sourceCommit,omitempty"`
}

// InspectUpstreams reads what each environment named by the target's
// promotesFrom currently has pinned, and compares it with the digests about to
// be deployed.
//
// Informational, and deliberately so: promotion policy — refusing a staging
// deploy of bits dev never ran, honouring requireSourceHealthy — belongs to the
// promote command. A deploy that *says* "these are not the bits dev tested" is
// more useful than one that refuses to run.
//
// Nothing here can fail. An environment with no overlay for this component, an
// unreadable kustomization, or the target naming itself yields a note or
// nothing at all.
func InspectUpstreams(root string, coord gitops.Coordinate, comp *gitops.ComponentConfig, target string, env gitops.EnvironmentConfig, pins []source.Pin) []Upstream {
	var out []Upstream
	for _, name := range env.PromotesFrom {
		// An environment that promotes from itself would compare the overlay
		// with the edit about to be made to it. deploy.yaml does not forbid it.
		if name == target {
			continue
		}
		out = append(out, inspectUpstream(root, coord, comp, name, pins))
	}
	return out
}

func inspectUpstream(root string, coord gitops.Coordinate, comp *gitops.ComponentConfig, upstream string, pins []source.Pin) Upstream {
	u := Upstream{Environment: upstream, Status: UpstreamUnknown}

	dir, err := gitops.ResolveOverlay(root, coord, comp, upstream)
	if err != nil {
		return u
	}
	k, _, err := kustomize.ReadKustomization(dir)
	if err != nil {
		return u
	}

	u.SourceCommit = k.CommonAnnotations[kustomize.AnnotationSourceCommit]
	u.Pinned = make(map[string]string, len(pins))

	status := UpstreamMatch
	for _, pin := range pins {
		img, found := k.FindImage(pin.Image)
		if !found || img.Digest == "" {
			if found {
				u.Pinned[pin.Image] = img.Pinned()
			}
			// Unpinned outranks differs: "there is nothing to compare" is the
			// more accurate thing to say about the whole environment.
			status = UpstreamUnpinned
			break
		}
		u.Pinned[pin.Image] = img.Digest
		if img.Digest != pin.Digest {
			status = UpstreamDiffers
		}
	}
	u.Status = status
	return u
}

// Describe renders the one-line reassurance, or the one-line qualification.
func (u Upstream) Describe(pins []source.Pin) string {
	switch u.Status {
	case UpstreamMatch:
		subject := "these digests"
		if len(pins) == 1 {
			subject = "this digest"
		}
		if u.SourceCommit != "" {
			return fmt.Sprintf("%s already runs %s (commit %s) — you are shipping the tested bits",
				u.Environment, subject, git.ShortSHA(u.SourceCommit))
		}
		return fmt.Sprintf("%s already runs %s — you are shipping the tested bits", u.Environment, subject)

	case UpstreamDiffers:
		image, digest := u.firstDisagreement(pins)
		return fmt.Sprintf("%s runs a different digest for %s (%s) — these bits have not run there",
			u.Environment, image, shortDigest(digest))

	case UpstreamUnpinned:
		image, _ := u.firstDisagreement(pins)
		return fmt.Sprintf("%s pins no digest for %s, so there is nothing to compare", u.Environment, image)

	default:
		return fmt.Sprintf("%s could not be read, so there is nothing to compare", u.Environment)
	}
}

// firstDisagreement names the first image, in declared order, that the upstream
// environment does not pin to the digest being deployed. Declared order keeps
// the message stable across runs.
func (u Upstream) firstDisagreement(pins []source.Pin) (image, digest string) {
	for _, pin := range pins {
		there, found := u.Pinned[pin.Image]
		if !found || there != pin.Digest {
			return pin.Image, there
		}
	}
	// Unreachable for differs and unpinned, but a plausible message beats an
	// empty one if a caller ever asks about a match.
	if len(pins) > 0 {
		return pins[0].Image, u.Pinned[pins[0].Image]
	}
	return "", ""
}

// Package dashboard serves the local Intropy integration dashboard: a small
// stdlib net/http server that exposes a read-only JSON API over the
// integrations discovered under a workspace root and serves the embedded SPA
// that renders them. It starts no integration processes — the only thing it
// executes is each system host's `graph` verb, to obtain the declared
// topology the flow view draws.
package dashboard

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"time"
)

// Options configures a dashboard server. The zero value is not usable; Root is
// required and Addr/Port select the listen address.
type Options struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Addr is the host/interface to bind, e.g. "127.0.0.1". Empty binds all.
	Addr string
	// Port is the TCP port to bind. 0 asks the OS for a free port.
	Port int
	// OpenBrowser opens the dashboard URL in the default browser on start.
	OpenBrowser bool
	// Version is reported by GET /api/health.
	Version string
	// Stdout and Stderr receive program output and diagnostics; both default
	// to the process streams when nil.
	Stdout io.Writer
	Stderr io.Writer
}

// shutdownTimeout bounds how long in-flight requests have to drain on Ctrl+C.
const shutdownTimeout = 5 * time.Second

// Serve starts the dashboard and blocks until ctx is cancelled (e.g. SIGINT)
// or the server fails. On cancellation it shuts down gracefully and returns
// nil; it returns a non-nil error only for a real startup or runtime failure.
func Serve(ctx context.Context, opts Options) error {
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	root := opts.Root
	if root == "" {
		root = "."
	}

	handler, err := newHandler(root, opts.Version, hostGraphProvider(root))
	if err != nil {
		return fmt.Errorf("run: %w", err)
	}

	addr := net.JoinHostPort(opts.Addr, fmt.Sprintf("%d", opts.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("run: cannot listen on %s: %w", addr, err)
	}

	url := displayURL(opts.Addr, ln.Addr())
	fmt.Fprintf(opts.Stderr, "Intropy dashboard running at %s\n", url)
	fmt.Fprintln(opts.Stderr, "Press Ctrl+C to stop.")

	if opts.OpenBrowser {
		if err := openBrowser(url); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not open browser: %v\n", err)
		}
	}

	srv := &http.Server{Handler: handler}
	errCh := make(chan error, 1)
	go func() {
		err := srv.Serve(ln)
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	select {
	case <-ctx.Done():
		fmt.Fprintln(opts.Stderr, "\nShutting down…")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			return fmt.Errorf("run: shutdown: %w", err)
		}
		return nil
	case err := <-errCh:
		if err != nil {
			return fmt.Errorf("run: server error: %w", err)
		}
		return nil
	}
}

// displayURL builds a browser-friendly URL. It uses the actual bound port
// (important when Port was 0) and rewrites wildcard bind hosts to localhost.
func displayURL(host string, addr net.Addr) string {
	port := 0
	if tcp, ok := addr.(*net.TCPAddr); ok {
		port = tcp.Port
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "localhost"
	}
	return fmt.Sprintf("http://%s", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
}

package dashboard

import (
	"context"
	"fmt"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// topologyProvider fetches the declared topologies for the workspace. Each
// entry's Path is the on-disk system directory (the handler normalizes it to
// a root-relative identifier). Per-host failures are returned as messages
// alongside the successes so one broken host cannot hide the rest.
type topologyProvider func(ctx context.Context) (entries []topology.Entry, errs []string)

// hostGraphProvider returns the default provider: it finds every scaffolded
// system host under root and asks each one to print its declared topology.
// Hosts scaffolded before the graph verb existed simply fail, which surfaces as
// an error the UI renders.
//
// The mechanics live in topology.RunGraph, which deploy init shares. What stays
// here is the dashboard's policy: never fail, report per host.
func hostGraphProvider(root string) topologyProvider {
	return func(ctx context.Context) ([]topology.Entry, []string) {
		hosts, _ := template.ListSystemHosts(root)
		var entries []topology.Entry
		var errs []string
		for _, h := range hosts {
			t, err := topology.RunGraph(ctx, h.Path)
			if err != nil {
				errs = append(errs, fmt.Sprintf("%s: %v", displayPath(root, h.Path), err))
				continue
			}
			// The system directory is the workspace directory holding the
			// host: components are scaffolded as its siblings.
			entries = append(entries, topology.Entry{Path: filepath.Dir(h.Path), Topology: *t})
		}
		return entries, errs
	}
}

// displayPath shortens a host directory to its root-relative form for error
// messages, matching the identifier space the rest of the API uses.
func displayPath(root, p string) string {
	if rel, err := filepath.Rel(root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

