.section {
  margin-top: 30px;
}

.section-title {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin: 0 0 12px;
}

.section-title .icon {
  width: 16px;
  height: 16px;
}

.kv {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.kv th,
.kv td {
  text-align: left;
  padding: 9px 14px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.kv tr:last-child th,
.kv tr:last-child td {
  border-bottom: none;
}

.kv th {
  width: 30%;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--surface-2);
}

.kv td {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  background: var(--surface);
}

.steps {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
